-- V21: Batch 4 — gold-standard content for 10 high-priority DSA problems.\n-- Gold-standard content; all problems remain in CONTENT_REVIEW until technical validation.\n\n-- 1 Max Consecutive Ones III\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),1,$$Identify the core sliding-window signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),2,$$Expand right and shrink left whenever zero count exceeds k.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),$$Find the longest subarray containing at most k zeroes.$$,$$Keywords: Max Consecutive Ones III; ask what structure can be reused instead of recomputed. Look for the sliding-window pattern and the strongest input constraint.$$,$$Use when a contiguous range is valid while a count of violations can be maintained.$$,$$Do not use when removing an element changes validity non-locally.$$,$$Expand right and shrink left whenever zero count exceeds k.$$,$$Expand right and shrink left whenever zero count exceeds k.$$,$$Sliding window with a zero counter.$$,$$Enumerating every range is O(n squared).$$,'O(n^2)','O(1)',$$Sliding window with a zero counter.$$,'O(n)','O(1)',$$left=0; zeros=0; for right: count zero; while zeros>k shrink left; update best$$,$$The window becomes valid again after removing enough zeroes, and each pointer moves only forward.$$,$$After shrinking, the current window contains at most k zeroes.$$,$$Forgetting to shrink repeatedly; using k as a number of flips performed rather than allowed.$$,$$Generalize to arbitrary bad-element budgets and stream processing when only the maximum length is needed.$$,$$public int longestOnes(int[] a,int k){int l=0,z=0,b=0;for(int r=0;r<a.length;r++){if(a[r]==0)z++;while(z>k)if(a[l++]==0)z--;b=Math.max(b,r-l+1);}return b;}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),$$What changes if the window must contain exactly k zeroes?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),$$How would you return the window indices?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),$$Why is this O(n) despite the nested while?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),$$How would you generalize to weighted violations?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='max-consecutive-ones'),$$Can this be processed as a stream?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='max-consecutive-ones'),$$7
