frequency arrays and update only entering/leaving characters.$$,'O(n) for fixed alphabet','O(1) for fixed alphabet',$$build need counts; slide a window of pattern length; add right char and remove left char; compare counts$$,$$Each window has exactly the pattern length, so matching frequency vectors is equivalent to being a permutation.$$,$$The frequency state always describes exactly the current window.$$,$$Wrong window length; forgetting to remove the outgoing character; comparing only distinct counts.$$,$$For Unicode use a map. For large alphabets, maintain a matched-counter instead of comparing the full vector.$$,$$public boolean checkInclusion(String s1,String s2){if(s1.length()>s2.length())return false;int[]a=new int[26],b=new int[26];for(char c:s1.toCharArray())a[c-'a']++;for(int i=0;i<s2.length();i++){b[s2.charAt(i)-'a']++;if(i>=s1.length())b[s2.charAt(i-s1.length())-'a']--;if(Arrays.equals(a,b))return true;}return false;}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='permutation-in-string'),$$How can you avoid Arrays.equals on every window?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='permutation-in-string'),$$What changes for Unicode?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='permutation-in-string'),$$Can you return the first matching index?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='permutation-in-string'),$$Why is the window exactly s1.length()?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='permutation-in-string'),$$How would you parallelize the search?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='permutation-in-string'),$$ab
