and subtract left$$,$$Positive values ensure adding right cannot reduce the sum and removing left cannot increase it.$$,$$Whenever the window is valid, shrinking from the left explores the shortest valid window ending at right.$$,$$Using it with negative numbers; failing to shrink repeatedly; returning n when no answer exists.$$,$$For negative values use prefix sums plus a monotonic deque. For streaming input, retain the necessary left boundary state.$$,$$public int minSubArrayLen(int target,int[] a){int l=0,sum=0,b=Integer.MAX_VALUE;for(int r=0;r<a.length;r++){sum+=a[r];while(sum>=target){b=Math.min(b,r-l+1);sum-=a[l++];}}return b==Integer.MAX_VALUE?0:b;}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='minimum-size-subarray-sum'),$$Why do positive values matter?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='minimum-size-subarray-sum'),$$How would you solve it with negative numbers?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='minimum-size-subarray-sum'),$$Can you return the actual range?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='minimum-size-subarray-sum'),$$Why does each index move at most once?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='minimum-size-subarray-sum'),$$How would you process an unbounded stream?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='minimum-size-subarray-sum'),$$7
