1$$,$$1$$,true,3);\n\n-- 4 Longest Repeating Character Replacement\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),1,$$Identify the core sliding-window signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),2,$$Expand right; if window length minus max frequency exceeds k, move left until valid.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),$$Find the longest substring that can be made uniform using at most k replacements.$$,$$Keywords: Longest Repeating Character Replacement; ask what structure can be reused instead of recomputed. Look for the sliding-window pattern and the strongest input constraint.$$,$$Track the most frequent character in the window and the number of replacements needed.$$,$$Do not use a fixed window when its validity depends on the current maximum frequency.$$,$$Expand right; if window length minus max frequency exceeds k, move left until valid.$$,$$Expand right; if window length minus max frequency exceeds k, move left until valid.$$,$$Use a frequency window and maintain the maximum frequency seen.$$,$$Enumerating all substrings is O(n squared).$$,'O(n^2)','O(1)',$$Use a frequency window and maintain the maximum frequency seen.$$,'O(n)','O(1)',$$count[right]++; maxFreq=max(maxFreq,count[right]); while windowLen-maxFreq>k decrement left; update best$$,$$A window is fixable exactly when all non-majority characters can be replaced within k operations.$$,$$The maintained window never requires more than k replacements after shrinking.$$,$$Decreasing maxFreq on every shrink unnecessarily; forgetting to shrink; confusing replacement count with distinct count.$$,$$For Unicode use a map. For large alphabets, the same invariant works with dynamic frequency storage.$$,$$public int characterReplacement(String s,int k){int[]c=new int[26];int l=0,m=0,b=0;for(int r=0;r<s.length();r++){m=Math.max(m,++c[s.charAt(r)-'A']);while(r-l+1-m>k)c[s.charAt(l++)-'A']--;b=Math.max(b,r-l+1);}return b;}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),$$Why is maxFreq allowed to be stale?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),$$What if lowercase or Unicode characters are allowed?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),$$Can you return the replacement operations?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),$$What changes when k=0?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),$$How would you test the invariant?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='longest-repeating-character-replacement'),$$ABAB
