7$$,$$3$$,true,3);\n\n-- 6 Find Minimum in Rotated Sorted Array\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),1,$$Identify the core binary-search signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),2,$$If nums[mid] > nums[right], the minimum is to the right; otherwise it is at mid or to the left.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),$$Find the minimum value in a rotated sorted array with distinct values.$$,$$Keywords: Find Minimum in Rotated Sorted Array; ask what structure can be reused instead of recomputed. Look for the binary-search pattern and the strongest input constraint.$$,$$The minimum is the only point where ordering wraps; compare midpoint with the right boundary.$$,$$Do not use this exact proof when duplicates are allowed without adapting the decision rule.$$,$$If nums[mid] > nums[right], the minimum is to the right; otherwise it is at mid or to the left.$$,$$If nums[mid] > nums[right], the minimum is to the right; otherwise it is at mid or to the left.$$,$$Use modified binary search.$$,$$Linear scan is O(n).$$,'O(n)','O(1)',$$Use modified binary search.$$,'O(log n)','O(1)',$$l=0;r=n-1; while l<r: m=...; if a[m]>a[r] l=m+1 else r=m; return a[l]$$,$$A midpoint greater than the right value proves the rotation point lies after midpoint.$$,$$The minimum always remains inside [left,right].$$,$$Comparing with left instead of right without the corresponding proof; using <= incorrectly; off-by-one errors.$$,$$With duplicates, equality may require shrinking the right boundary and can degrade to O(n).$$,$$public int findMin(int[] a){int l=0,r=a.length-1;while(l<r){int m=l+(r-l)/2;if(a[m]>a[r])l=m+1;else r=m;}return a[l];}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),$$Why compare with the rightmost value?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),$$What changes with duplicates?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),$$How is this related to rotated-array search?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),$$Can you return the rotation index?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='find-min-rotated-array'),$$What happens for an unrotated array?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='find-min-rotated-array'),$$5
