$$,$$1$$,true,3);\n\n-- 7 Min Stack\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='min-stack'),1,$$Identify the core stack signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='min-stack'),2,$$Store the minimum associated with each stack depth, or maintain a second min stack.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='min-stack'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='min-stack'),$$Design a stack that returns its minimum in constant time.$$,$$Keywords: Min Stack; ask what structure can be reused instead of recomputed. Look for the stack pattern and the strongest input constraint.$$,$$Each pushed value needs access to the minimum of everything below it.$$,$$Do not scan the stack on every getMin call.$$,$$Store the minimum associated with each stack depth, or maintain a second min stack.$$,$$Store the minimum associated with each stack depth, or maintain a second min stack.$$,$$Use a second stack containing the minimum at each relevant depth.$$,$$A scan for minimum costs O(n) per getMin.$$,'O(n)','O(1)',$$Use a second stack containing the minimum at each relevant depth.$$,'O(1) per operation','O(n)',$$push value and update min stack; pop both when needed; getMin reads min top$$,$$The top of the min stack is the minimum among all active values.$$,$$After every operation, minStack.top equals the minimum of stack contents.$$,$$Not updating the min stack for duplicate minima; popping only one stack; using Integer comparison incorrectly.$$,$$Encode min values in one stack with arithmetic to reduce structures, but account for overflow; or use a pair object for clarity.$$,$$class MinStack { Deque<Integer>s=new ArrayDeque<>(),m=new ArrayDeque<>(); public void push(int x){s.push(x);m.push(m.isEmpty()?x:Math.min(x,m.peek()));} public void pop(){s.pop();m.pop();} public int top(){return s.peek();} public int getMin(){return m.peek();} }$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='min-stack'),$$Why store duplicate minima?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='min-stack'),$$Can this use one stack?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='min-stack'),$$What is the memory tradeoff?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='min-stack'),$$How would you make operations thread-safe?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='min-stack'),$$How would you support getMax too?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='min-stack'),$$push -2; push 0; push -3; getMin$$,$$-3$$,false,1),\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='min-stack'),$$push 2; push 2; pop; getMin$$,$$2$$,false,2),\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='min-stack'),$$push 5; pop; getMin$$,$$error$$,true,3);\n\n-- 8 Evaluate Reverse Polish Notation\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),1,$$Identify the core stack signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),2,$$Push numbers. For an operator, pop right operand first, then left operand, compute, and push the result.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),$$Evaluate an arithmetic expression written in postfix notation.$$,$$Keywords: Evaluate Reverse Polish Notation; ask what structure can be reused instead of recomputed. Look for the stack pattern and the strongest input constraint.$$,$$Operands accumulate until an operator consumes the top two values.$$,$$Do not pop operands in the wrong order; subtraction and division are not commutative.$$,$$Push numbers. For an operator, pop right operand first, then left operand, compute, and push the result.$$,$$Push numbers. For an operator, pop right operand first, then left operand, compute, and push the result.$$,$$Evaluate tokens once with a stack.$$,$$Repeatedly searching the expression for reducible subexpressions can be quadratic.$$,'O(n^2)','O(n)',$$Evaluate tokens once with a stack.$$,'O(n)','O(n)',$$for token: number->push; operator->b=pop,a=pop,push(a op b); return pop$$,$$Postfix notation guarantees that the top two stack values are exactly the operands of the next operator.$$,$$Before each operator, the stack contains the values of all completed subexpressions preceding it.$$,$$Reversing operand order; integer division semantics; insufficient operands; treating negative numbers as operators.$$,$$For untrusted expressions validate token count and numeric range. For extensibility map operators to functions carefully.$$,$$public int evalRPN(String[] t){Deque<Integer>s=new ArrayDeque<>();for(String x:t){if(x.length()==1&&"+-*/".indexOf(x.charAt(0))>=0){int b=s.pop(),a=s.pop();switch(x.charAt(0)){case '+':s.push(a+b);break;case '-':s.push(a-b);break;case '*':s.push(a*b);break;default:s.push(a/b);}}else s.push(Integer.parseInt(x));}return s.pop();}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),$$Why is operand order important?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),$$How would you add exponentiation?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),$$How should malformed expressions be handled?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),$$What changes for floating point values?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),$$How could operators be made extensible?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='evaluate-reverse-polish'),$$5
