10 6 9 3 + -11 * / * 17 + 5 +$$,$$22$$,true,3);\n\n-- 9 Linked List Cycle\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),1,$$Identify the core linked-list signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),2,$$Move slow one step and fast two steps. If they meet, a cycle exists.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),$$Determine whether a singly linked list contains a cycle.$$,$$Keywords: Linked List Cycle; ask what structure can be reused instead of recomputed. Look for the linked-list pattern and the strongest input constraint.$$,$$Two pointers moving at different speeds eventually meet inside a cycle.$$,$$Do not rely on node values because values may repeat.$$,$$Move slow one step and fast two steps. If they meet, a cycle exists.$$,$$Move slow one step and fast two steps. If they meet, a cycle exists.$$,$$Use Floyd's tortoise-and-hare algorithm.$$,$$A HashSet of visited nodes uses O(n) space.$$,'O(n)','O(n)',$$Use Floyd's tortoise-and-hare algorithm.$$,'O(n)','O(1)',$$slow=head; fast=head; while fast and fast.next: slow=slow.next; fast=fast.next.next; if slow==fast return true; return false$$,$$In an acyclic list fast reaches null. In a cyclic list, relative speed causes fast to catch slow.$$,$$If a cycle exists, both pointers remain in the cycle and their relative distance changes by one node per iteration.$$,$$Comparing values instead of node identity; dereferencing fast.next.next unsafely; starting pointers inconsistently.$$,$$Extend Floyd's method to find the cycle entry and cycle length. For concurrent structures, define synchronization semantics separately.$$,$$public boolean hasCycle(ListNode h){ListNode s=h,f=h;while(f!=null&&f.next!=null){s=s.next;f=f.next.next;if(s==f)return true;}return false;}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),$$How do you find the cycle entry?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),$$Why does fast eventually meet slow?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),$$Can you find the cycle length?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),$$What if node values repeat?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='linked-list-cycle'),$$What synchronization concerns arise with concurrent mutation?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='linked-list-cycle'),$$1
