ctly once, so every node and edge is processed a constant number of times.$$,$$When a node is processed, its children are exchanged exactly once before their subtrees are transformed.$$,$$Swapping after recursive calls without understanding references; forgetting null handling; assuming balanced height.$$,$$For deep trees use an explicit stack. The same pattern applies to mirror transformations in other hierarchical structures.$$,$$public TreeNode invertTree(TreeNode n){if(n==null)return null;TreeNode t=n.left;n.left=n.right;n.right=t;invertTree(n.left);invertTree(n.right);return n;}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='invert-binary-tree'),$$Can you implement it iteratively?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='invert-binary-tree'),$$What is the worst-case recursion depth?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='invert-binary-tree'),$$How would you preserve the original tree instead of mutating it?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='invert-binary-tree'),$$What is the space complexity for a balanced tree?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='invert-binary-tree'),$$How would you test structural equality after inversion?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='invert-binary-tree'),$$3
